{
  "decisions": [
    {
      "entity_path": "config/archive_format",
      "change_type": "reject",
      "reasoning": "We rejected zstd because the downstream importer cannot decode it. The importer accepts zip and gzip. Use gzip for the smallest compatible export until the importer gains zstd support.",
      "constraint": "Nightly archives must be decodable by the downstream importer.",
      "stale_when": "Downstream importer adds tested zstd support."
    }
  ],
  "note": "This file is independent of any connected memory server."
}

{
  "status": "applied",
  "key": "archive_format",
  "value": "gzip",
  "rationale": "Among the three supported formats (zip 12 MB, gzip 9 MB, zstd 6 MB), zstd is the absolute smallest but is explicitly rejected by the maintained decision record because the downstream importer cannot decode it — and current evidence confirms the importer has not been upgraded. gzip at 9 MB is therefore the smallest format that remains compatible with the downstream importer, as the decision record directs."
}
